import { Tweet } from './Tweet';
import { Box } from 'styled-system/jsx';
import type { TweetGroup } from '~/types/bluebird';

interface GroupedTweetProps {
  group: TweetGroup;
  onCopy: (text: string, type: 'text' | 'link') => void;
}

export function GroupedTweet({ group, onCopy }: GroupedTweetProps) {
  const onCopyGroup = (type: 'text' | 'link') => {
    const textToCopy = group.tweets
      .map((tweet) => (type === 'text' ? tweet.data.text : tweet.data.url))
      .join('\n\n');
    onCopy(textToCopy, type);
  };

  return (
    <Box borderBottom="1px solid border.default">
      {group.tweets.map((tweet, index, arr) => (
        <Tweet
          key={tweet.id}
          tweet={tweet.data}
          hideBottom={index !== arr.length - 1}
          hideInfo={index !== 0}
          showLine
          onCopy={(_, type) => onCopyGroup(type)}
        />
      ))}
    </Box>
  );
}
