import { Link } from '../ui/link';
import { Text } from '../ui/text';
import { formatTweetText } from './TweetEntities';
import { formatProfilePictureUrl } from '~/utils/image';
import { Box, Divider, HStack, Stack, styled } from 'styled-system/jsx';
import type { PrunedTweet } from '~/utils/prune-tweets';

interface TweetProps {
  tweet: PrunedTweet;
  hideBottom?: boolean;
  hideInfo?: boolean;
  showLine?: boolean;
  quoted?: boolean;
  onCopy: (text: string, type: 'text' | 'link') => void;
}

export function Tweet({ tweet, hideBottom, hideInfo, showLine, quoted, onCopy }: TweetProps) {
  const tweetDate = new Date(tweet.createdAt);
  const today = new Date();
  const isToday =
    tweetDate.getDate() === today.getDate() &&
    tweetDate.getMonth() === today.getMonth() &&
    tweetDate.getFullYear() === today.getFullYear();

  const dateTimeOptions: Intl.DateTimeFormatOptions = {
    year: 'numeric',
    month: 'numeric',
    day: 'numeric'
  };

  if (isToday) {
    dateTimeOptions.hour = '2-digit';
    dateTimeOptions.minute = '2-digit';
  }

  return (
    <Box
      className="tweet"
      data-tweet-id={tweet.id}
      cursor="pointer"
      display="flex"
      borderBottomWidth={hideBottom ? '0' : '1px'}
      borderColor="border.default"
      px={quoted ? 0 : '4'}
      pt={hideInfo || quoted ? 0 : '4'}
      pb={hideBottom || quoted ? 0 : '4'}
      transitionDuration="200ms"
      transitionProperty="colors"
      _hover={{ bg: 'bg.subtle' }}
    >
      <Link
        href={tweet.url}
        target="_blank"
        rel="noopener noreferrer"
        display="flex"
        gap="3"
        alignItems="flex-start"
        w="full"
        textDecoration="unset"
        _hover={{ textDecoration: 'unset' }}
      >
        <Stack gap="0" flexShrink="0" alignItems="center" w={quoted ? '8' : '12'} h="full">
          {!hideInfo && (
            <styled.img
              src={formatProfilePictureUrl(tweet.author.profilePicture)}
              alt={tweet.author.name}
              objectFit="cover"
              borderRadius="full"
              w={quoted ? '8' : '12'}
              h={quoted ? '8' : '12'}
            />
          )}
          {showLine && (
            <Box
              flex="1"
              borderLeft="3px solid"
              borderLeftColor="border.muted"
              height="full"
              mb={!hideBottom ? '8' : 0}
            ></Box>
          )}
        </Stack>
        <Stack gap="0" direction="column" flexGrow="1" minW="0" h="full" overflow="hidden">
          {!hideInfo && (
            <HStack gap="1" alignItems="center" mb="0.5" flexWrap="wrap">
              <HStack flexGrow="1" alignItems="center">
                <Text
                  color="fg.default"
                  textOverflow="ellipsis"
                  textWrap="nowrap"
                  fontSize={quoted ? 'sm' : 'base'}
                  fontWeight="bold"
                  overflow="hidden"
                >
                  {tweet.author.name}
                </Text>
                <Text
                  color="fg.muted"
                  textOverflow="ellipsis"
                  textWrap="nowrap"
                  fontSize={quoted ? 'xs' : 'sm'}
                  overflow="hidden"
                >
                  @{tweet.author.userName}
                </Text>
              </HStack>
              <Text color="fg.muted" fontSize={quoted ? 'xs' : 'sm'}>
                {tweetDate.toLocaleString([], dateTimeOptions)}
              </Text>
            </HStack>
          )}
          <Text
            flex="1"
            w="full"
            h="full"
            mt={hideInfo ? '4' : 0}
            color="fg.default"
            wordBreak="break-word"
            fontSize={quoted ? 'sm' : 'base'}
            whiteSpace="pre-wrap"
          >
            {formatTweetText(tweet.text, tweet.entities)}
          </Text>
          {(tweet.quoted_tweet || tweet.retweeted_tweet) && (
            <Box border="1px solid" borderColor="border.default" rounded="xl" mt="2" p={2}>
              {tweet.retweeted_tweet && (
                <Tweet tweet={tweet.retweeted_tweet} onCopy={onCopy} hideBottom quoted />
              )}
              {tweet.quoted_tweet && (
                <Tweet tweet={tweet.quoted_tweet} onCopy={onCopy} hideBottom quoted />
              )}
            </Box>
          )}

          {hideBottom && !quoted && <Divider mt="4" />}
          {!hideBottom && (
            <HStack justifyContent="space-between" h="full" mt="2" color="fg.muted">
              <HStack
                onClick={(e) => {
                  e.preventDefault();
                  onCopy(tweet.text, 'text');
                }}
                cursor="pointer"
                justifyContent="center"
                alignItems="center"
                spaceX="1"
                color="fg.default"
              >
                <svg
                  className="w-4 h-4"
                  fill="none"
                  stroke="currentColor"
                  viewBox="0 0 24 24"
                  xmlns="http://www.w3.org/2000/svg"
                >
                  <path
                    strokeLinecap="round"
                    strokeLinejoin="round"
                    strokeWidth="2"
                    d="M8 16H6a2 2 0 01-2-2V6a2 2 0 012-2h8a2 2 0 012 2v2m-6 12h8a2 2 0 002-2v-8a2 2 0 00-2-2h-8a2 2 0 00-2 2v8a2 2 0 002 2z"
                  ></path>
                </svg>
              </HStack>
              <Link
                href={tweet.twitterUrl}
                target="_blank"
                rel="noopener noreferrer"
                color="fg.default"
              >
                <HStack cursor="pointer" justifyContent="center" alignItems="center" spaceX="1">
                  <svg
                    className="w-4 h-4"
                    fill="none"
                    stroke="currentColor"
                    viewBox="0 0 24 24"
                    xmlns="http://www.w3.org/2000/svg"
                  >
                    <path
                      strokeLinecap="round"
                      strokeLinejoin="round"
                      strokeWidth="2"
                      d="M10 6H6a2 2 0 00-2 2v10a2 2 0 002 2h10a2 2 0 002-2v-4M14 4h6m0 0v6m0-6L10 14"
                    ></path>
                  </svg>
                </HStack>
              </Link>
              <HStack cursor="pointer" justifyContent="center" alignItems="center" spaceX="1">
                <svg
                  className="w-4 h-4"
                  fill="none"
                  stroke="currentColor"
                  viewBox="0 0 24 24"
                  xmlns="http://www.w3.org/2000/svg"
                >
                  <path
                    strokeLinecap="round"
                    strokeLinejoin="round"
                    strokeWidth="2"
                    d="M4.318 6.318a4.5 4.5 0 000 6.364L12 20.364l7.682-7.682a4.5 4.5 0 00-6.364-6.364L12 7.636l-1.318-1.318a4.5 4.5 0 00-6.364 0z"
                  ></path>
                </svg>
              </HStack>
              <HStack
                onClick={(e) => {
                  e.preventDefault();
                  onCopy(tweet.url, 'link');
                }}
                cursor="pointer"
                justifyContent="center"
                alignItems="center"
                spaceX="1"
              >
                <svg
                  className="w-4 h-4"
                  fill="none"
                  stroke="currentColor"
                  viewBox="0 0 24 24"
                  xmlns="http://www.w3.org/2000/svg"
                >
                  <path
                    strokeLinecap="round"
                    strokeLinejoin="round"
                    strokeWidth="2"
                    d="M13.828 10.172a4 4 0 00-5.656 0l-4 4a4 4 0 105.656 5.656l1.102-1.101m-.758-4.899a4 4 0 005.656 0l4-4a4 4 0 00-5.656-5.656l-1.1 1.1"
                  ></path>
                </svg>
              </HStack>
              <Box />
            </HStack>
          )}
        </Stack>
      </Link>
    </Box>
  );
}
